{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Mithramycin, a large glycosylated polyketide with multiple sugars and hydroxyls, achieved only a 0.12 CSF:plasma ratio in monkeys and little normal-brain distribution, indicating poor CNS access for this class of highly glycosylated, polar natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a cardiac glycoside with high molecular weight and multiple polar groups, showed CSF/plasma ratios of only 0.01-0.03 in dogs, demonstrating that glycosylated natural products with similar physicochemical burdens do not readily cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Gentamicin, a highly polar aminosugar-containing antibiotic, produced inadequate CSF levels after systemic administration in humans, supporting poor CNS access for molecules with multiple basic amines and hydroxyls.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Doxycycline, a polyhydroxylated tetracycline-like polyketide, showed only traces in rat brain after systemic dosing, supporting poor BBB penetration for polyhydroxy polyketide scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "CMT-3, a lipophilic chemically modified tetracycline, accumulated in rat brain (4 µg/g), showing that some tetracycline-like molecules can achieve brain exposure; however, the query is much more polar and larger, limiting transfer of this positive result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly polar, aminosugar-containing anthracycline-like molecule with multiple H-bond donors and a predominantly charged state at physiological pH. Transferable experimental evidence from glycosylated and polyhydroxylated natural products (mithramycin, digitoxin, gentamicin, doxycycline) consistently shows poor CSF/brain penetration after systemic dosing, and the physicochemical prior indicates strong efflux liability. Occasional permeable analogues are much smaller or more lipophilic and do not overcome the dominant poor-penetration pattern. Therefore meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain/CSF measurement for the exact query or daunorubicinol under brain-tumor conditions",
    "Morgan similarities to evidence molecules are low (<0.3), limiting quantitative transfer",
    "Tumor-associated BBB disruption and possible active uptake in glioma were not directly assessed",
    "Efflux transporter substrate status of the query was not experimentally confirmed"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

